mapper.select:
SELECT l.*, u.user_name AS userName, c.user_name AS creditUserName, m.user_name AS managerUserName FROM loan_apply l LEFT JOIN `user` u ON u.user_id = l.user_id LEFT JOIN `user` c ON c.user_id = l.credit_user_id LEFT JOIN `user` m ON m.user_id = l.manager_user_id
AND u.user_id = #{userId}
AND l.apply_no LIKE CONCAT('%', #{applyNo}, '%')
AND u.user_name LIKE CONCAT('%', #{userName}, '%')
AND l.apply_status = #{applyStatus}
ORDER BY l.loan_id ASC
